"""Build the saucer's offline review player from the rendered timeline."""
from pathlib import Path
from html import escape
import json,re
ROOT=Path(__file__).resolve().parent;OUT=ROOT/'integrated';s=json.loads((OUT/'shot.json').read_text());e=lambda x:escape(str(x),quote=True)
style=re.search(r'<style>(.*?)</style>',(ROOT.parent/'fan/integrated/index.html').read_text(),re.S).group(1)
cards=[]
for k,f in enumerate(s['keys'],1):
    t=s['frames'][f]['source_time'];cards.append(f'<figure><div class="pair"><img src="source-{k:02d}.jpg" alt="NASA CGI archive frame {t:.3f} seconds"><img src="key-{k:02d}.png" alt="Assembled saucer key {k}"></div><figcaption>Key {k} · source {t:.3f} s · rendered frame {f}</figcaption></figure>')
note=s.get('review_note','Independent source-pose and normal-speed playback review pending.')
badge='DRAWING IDENTITY REPAIR PENDING' if s.get('review_status')=='drawing_identity_repair_pending' else 'ASSEMBLED REVIEW COPY'
reviews=' · '.join(f'<a href="{f.name}">Independent review {i}</a>' for i,f in enumerate(sorted(OUT.glob('review-v*.json')),1))
fit=s['mask_fit']
html=f'''<!doctype html><html lang="en"><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><title>Flying saucer · assembled review · Secondhand Motion</title><link rel="icon" href="../../../favicon.svg"><style>{style}</style><body><main class="wrap"><nav><a href="../../../index.html">Secondhand Motion</a><a href="../../wave2-keyframes.html">All ten subjects</a><a href="../index.html">Earlier isolated keys</a></nav><h1>A saucer borrows an entry attitude.</h1><p class="meta">{s['frame_count']} rendered frames · {s['fps']} fps · {len(s['keys'])} full-scene keys · {s['duration']:.3f} seconds</p><p><span class="badge">{badge}</span></p><div class="player"><video id="film" controls playsinline preload="metadata" poster="poster.png" src="cartoon.mp4"></video></div><div class="tabs" aria-label="View"><button data-src="cartoon.mp4" data-poster="poster.png" aria-pressed="true">Cartoon</button><button data-src="comparison.mp4" data-poster="comparison-poster.jpg" aria-pressed="false">Source beside cartoon</button><button data-src="source-excerpt.mp4" data-poster="source-01.jpg" aria-pressed="false">Source</button></div><p class="meta">The doodle takes its attitude and movement from an aeroshell in NASA CGI, not physical UFO footage. The shell drifts right and down, then back left and up; the lower rim retains the camera crop. {e(note)}</p><h2>Eight moments, fully assembled.</h2><p class="meta">NASA CGI archive at left; its attitude transferred to the original doodle at right.</p><section class="keys">{''.join(cards)}</section><details><summary>References and review</summary><p>Quick, Draw! key {e(s['design']['key_id'])}. All six original strokes are retained: the lopsided rim, angular dome and four small marks. Quick, Draw! contributors / Google Creative Lab, CC BY 4.0. Background cloud lines drawn once by agent against the CGI source. Background movement was not measured.</p><p>Archive: <a href="{e(s['source']['page_url'])}">DPLR, NASA’s Ticket to Planetary Entry</a>, clip-relative {s['source']['interval_seconds'][0]:.3f}–{s['source']['interval_seconds'][1]:.3f} s. Source kind: NASA CGI animation. Archive rights were not supplied in the candidate manifest.</p><p>SAM 2.1 landmarks drive the observed top and cap trajectories. Filled native rim/dome silhouette against source SAM: mean {fit['mean']:.3f}, minimum {fit['minimum']:.3f}. SAM predicted IoU spans {s['mask_provenance']['predicted_confidence']['minimum']:.3f}–{s['mask_provenance']['predicted_confidence']['maximum']:.3f}; it is not ground-truth overlap. The mask-fit bar is {'met' if fit['pass'] else 'not met'} (mean≥0.65, minimum≥0.45). This overlap is distinct from model-predicted confidence and does not establish identity or motion quality. Hidden lower contours are not verified where the source crops them. Final key observations restore the visible rim tip despite mask-edge false positives; <a href="source-key-constraints.json">crop/clearance constraints</a> record that correction.</p><p><a href="shot.json">Timeline and anchors</a> · <a href="assembly-checks.json">Checks</a> · <a href="mask-fit.json">Filled silhouette fit</a> · <a href="source-masks/provenance.json">SAM provenance</a> · <a href="traced.json">Character traces</a> · <a href="design.png">Original doodle</a> · {reviews}</p><p>Recognition classifier and independent normal-speed playback remain unrun. No training ran. This review copy is not release approved.</p></details><footer><a href="cartoon.mp4" download>Download cartoon</a> · <a href="comparison.mp4" download>Download synchronized comparison</a></footer></main><script>
const v=document.querySelector('#film');for(const b of document.querySelectorAll('button[data-src]'))b.addEventListener('click',()=>{{const t=v.currentTime;const playing=!v.paused;for(const x of document.querySelectorAll('button[data-src]'))x.setAttribute('aria-pressed',String(x===b));v.pause();v.poster=b.dataset.poster;v.src=b.dataset.src;v.addEventListener('loadedmetadata',()=>{{v.currentTime=Math.min(t,v.duration||0);if(playing)v.play().catch(()=>{{}})}},{{once:true}});v.load()}});
</script></html>'''
(OUT/'index.html').write_text(html)
print(OUT/'index.html')
